import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
import 'package:pdf/pdf.dart';
import 'package:pdf/widgets.dart' as pw;
import 'package:printing/printing.dart';

class ReportsV2Page extends StatefulWidget { const ReportsV2Page({super.key}); @override State<ReportsV2Page> createState()=>_ReportsV2PageState(); }
class _ReportsV2PageState extends State<ReportsV2Page> {
  final db=FirebaseFirestore.instance;
  String report='Sales',period='Daily',stockScope='All'; DateTime from=DateTime.now(),to=DateTime.now();
  bool loading=true,retailUser=false,admin=false; String? assignedShopId,assignedShopName,error; List<Map<String,dynamic>> rows=[],shops=[],products=[];
  final allTypes=const ['Sales','Receipt','Payments','Outstanding','Commission','Production','Expenses','Salary','Capital','Stock Management','Cash Management','Profit/Loss'];
  List<String> get types=>retailUser?const['Sales','Outstanding','Commission','Stock Management','Cash Management']:admin?allTypes:const['Sales','Receipt','Payments','Outstanding','Commission','Production','Expenses','Salary','Capital','Stock Management','Cash Management'];
  CollectionReference<Map<String,dynamic>> c(String n)=>db.collection('sharedData').doc('dailyHisab').collection(n);
  double n(dynamic v)=>v is num?v.toDouble():double.tryParse('$v')??0;
  DateTime d(dynamic v)=>v is Timestamp?v.toDate():v is DateTime?v:DateTime.tryParse('$v')??DateTime.fromMillisecondsSinceEpoch(0);
  String date(DateTime x)=>'${x.day.toString().padLeft(2,'0')}-${x.month.toString().padLeft(2,'0')}-${x.year}';
  String money(dynamic v)=>'₹${n(v).toStringAsFixed(2)}';
  bool inRange(DateTime x)=>!x.isBefore(DateTime(from.year,from.month,from.day))&&!x.isAfter(DateTime(to.year,to.month,to.day,23,59,59));
  @override void initState(){super.initState();_init();}
  Future<void> _init()async{try{final uid=FirebaseAuth.instance.currentUser?.uid;if(uid==null)throw StateError('Please login again.');final p=(await db.collection('users').doc(uid).get()).data()??{};retailUser=p['role']=='retail_shop_user';admin=p['role']=='admin';assignedShopId=p['shopId']?.toString();assignedShopName=p['shopName']?.toString();final ps=await c('products').get();final ss=retailUser?null:await c('retailShops').get();if(!mounted)return;setState((){products=ps.docs.map((x)=>{'id':x.id,...x.data()}).where((x)=>x['active']!=false).toList();shops=ss?.docs.map((x)=>{'id':x.id,...x.data()}).where((x)=>x['active']!=false).toList()??[];report=types.first;loading=false;});await _load();}catch(e){if(mounted)setState((){error='$e';loading=false;});}}
  Future<List<Map<String,dynamic>>> coll(String name,{String? shopField,String? shop})async{Query<Map<String,dynamic>> q=c(name);if(retailUser&&shop!=null&&shopField!=null)q=q.where(shopField,isEqualTo:shop);final s=await q.get();return s.docs.map((x)=>{'id':x.id,...x.data()}).where((x)=>inRange(d(x['date']))).toList();}
  void setPeriod(String v){final now=DateTime.now();var a=now,b=now;if(v=='Monthly'){a=DateTime(now.year,now.month,1);b=DateTime(now.year,now.month+1,0);}else if(v=='Quarterly'){final m=((now.month-1)~/3)*3+1;a=DateTime(now.year,m,1);b=DateTime(now.year,m+3,0);}else if(v=='6 Monthly'){final m=now.month<=6?1:7;a=DateTime(now.year,m,1);b=DateTime(now.year,m+6,0);}else if(v=='Yearly'){a=DateTime(now.year,1,1);b=DateTime(now.year,12,31);}setState((){period=v;from=a;to=b;});_load();}
  Future<void> _load()async{if(!mounted)return;setState(()=>loading=true);try{if(!types.contains(report)){setState(()=>report=types.first);}List<Map<String,dynamic>> out=[];
    if(report=='Sales'||report=='Outstanding'||report=='Commission'){out=await coll('sales',shopField:'shopId',shop:assignedShopId);if(!retailUser&&shopId!=null)out=out.where((x)=>x['shopId']?.toString()==shopId).toList();if(productId!=null)out=out.where((x)=>(x['items'] is List)&&((x['items'] as List).any((i)=>i is Map&&i['productId']?.toString()==productId))).toList();if(report=='Outstanding')out=out.where((x)=>n(x['outstanding'])>0).toList();}
    else if(report=='Receipt'||report=='Payments'){out=await coll('transactions');final t=report=='Receipt'?'Receipt':'Payment';out=out.where((x)=>x['type']?.toString()==t).toList();}
    else if(report=='Production')out=await coll('production');
    else if(report=='Expenses')out=await coll('productionExpenses');
    else if(report=='Salary')out=await coll('salary');
    else if(report=='Capital')out=await coll('capital');
    else if(report=='Stock Management')out=await _stock();
    else if(report=='Cash Management')out=await _cash();
    else if(report=='Profit/Loss')out=await _profit();
    out.sort((a,b)=>d(b['date']).compareTo(d(a['date'])));if(mounted)setState((){rows=out;loading=false;error=null;});
  }catch(e){if(mounted)setState((){error='$e';loading=false;});}}
  Future<List<Map<String,dynamic>>> _stock()async{
    final p=products,t=await coll('stockTransfers',shopField:'shopId',shop:assignedShopId),r=await coll('stockOtherReceived',shopField:'shopId',shop:assignedShopId),s=await coll('sales',shopField:'shopId',shop:assignedShopId),prod=retailUser?const <Map<String,dynamic>>[]:await coll('production');
    final out=<Map<String,dynamic>>[];
    if(retailUser||stockScope=='Retail Shops'||stockScope=='All'){final ids=retailUser?[assignedShopId!]:shops.map((x)=>x['id'].toString()).toList();for(final sid in ids){final sn=retailUser?(assignedShopName??'Assigned Shop'):shops.firstWhere((x)=>x['id'].toString()==sid,orElse:()=>{'name':sid})['name']?.toString()??sid;for(final x in p){final pid=x['id'].toString();final incoming=t.where((z)=>z['shopId']?.toString()==sid&&z['productId']?.toString()==pid).fold(0.0,(a,z)=>a+n(z['quantity']));final other=r.where((z)=>z['shopId']?.toString()==sid&&z['productId']?.toString()==pid).fold(0.0,(a,z)=>a+n(z['quantity']));final sold=s.where((z)=>z['shopId']?.toString()==sid).fold(0.0,(a,z){final items=z['items'];if(items is! List)return a;return a+items.whereType<Map>().where((i)=>i['productId']?.toString()==pid).fold(0.0,(q,i)=>q+n(i['quantity']));});out.add({'particular':'$sn • ${x['name']??pid}','location':sn,'productName':x['name']??pid,'quantity':incoming+other-sold});}}}
    if(!retailUser&&(stockScope=='Production Unit'||stockScope=='All')){for(final x in p){final pid=x['id'].toString();final made=prod.where((z)=>z['productId']?.toString()==pid).fold(0.0,(a,z)=>a+n(z['quantity']));final moved=t.where((z)=>z['productId']?.toString()==pid).fold(0.0,(a,z)=>a+n(z['quantity']));out.add({'particular':'Production Unit • ${x['name']??pid}','location':'Production Unit','productName':x['name']??pid,'quantity':made-moved});}}
    return out;
  }
  Future<List<Map<String,dynamic>>> _cash()async{final out=<Map<String,dynamic>>[];if(retailUser){final s=await coll('sales',shopField:'shopId',shop:assignedShopId);for(final x in s){if(n(x['paymentReceived'])>0)out.add({'date':x['date'],'particular':'Sales - ${assignedShopName??''}','amount':n(x['paymentReceived']),'account':x['paymentAccount']??'Cash'});}return out;}final tx=await coll('transactions'),s=await coll('sales'),sal=await coll('salary'),e=await coll('productionExpenses'),cap=await coll('capital');for(final x in tx)out.add({'date':x['date'],'particular':'${x['type']??''} - ${x['partyName']??x['description']??''}','amount':n(x['amount']),'account':x['paymentAccount']??x['paymentMode']??'Cash'});for(final x in s)if(n(x['paymentReceived'])>0)out.add({'date':x['date'],'particular':'Sales - ${x['shopName']??''}','amount':n(x['paymentReceived']),'account':x['paymentAccount']??'Cash'});for(final x in sal)out.add({'date':x['date'],'particular':'Salary - ${x['workerName']??''}','amount':n(x['amount']),'account':x['paymentAccount']??'Cash'});for(final x in e)out.add({'date':x['date'],'particular':'Expense - ${x['head']??x['name']??''}','amount':n(x['amount']),'account':x['paymentAccount']??'Cash'});for(final x in cap)out.add({'date':x['date'],'particular':'Capital - ${x['type']??''}','amount':n(x['amount']),'account':x['paymentAccount']??'Cash'});return out;}
  Future<List<Map<String,dynamic>>> _profit()async{final s=await coll('sales'),e=await coll('productionExpenses'),sal=await coll('salary');final gross=s.fold(0.0,(a,x)=>a+n(x['grossAmount']));final com=s.fold(0.0,(a,x)=>a+n(x['commission']));final ex=e.fold(0.0,(a,x)=>a+n(x['amount']));final sa=sal.fold(0.0,(a,x)=>a+n(x['amount']));return [{'particular':'Gross Sales','amount':gross},{'particular':'Commission','amount':com},{'particular':'Expenses','amount':ex},{'particular':'Salary','amount':sa},{'particular':'Profit / Loss','amount':gross-com-ex-sa}];}
  String? shopId,productId;
  String particular(Map<String,dynamic>x)=>(x['particular']??x['shopName']??x['productName']??x['workerName']??x['partyName']??x['type']??x['head']??'').toString();
  double amount(Map<String,dynamic>x)=>n(x['amount']??x['netAmount']??x['grossAmount']??x['quantity']);
  double get total=>rows.fold(0.0,(a,x)=>a+amount(x));
  Future<void> pdf()async{if(rows.isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('No report data to export.')));return;}await Printing.layoutPdf(onLayout:(format)async{final doc=pw.Document();doc.addPage(pw.MultiPage(pageFormat:PdfPageFormat.a4,build:(_)=>[pw.Text('DAILY HISAB - $report REPORT',style:pw.TextStyle(fontSize:18,fontWeight:pw.FontWeight.bold)),pw.Text('Period: ${date(from)} to ${date(to)}'),pw.SizedBox(height:12),pw.TableHelper.fromTextArray(headers:const['Date','Particular','Amount'],data:rows.map((x)=>[date(d(x['date'])),particular(x),amount(x).toStringAsFixed(2)]).toList()),pw.SizedBox(height:10),pw.Align(alignment:pw.Alignment.centerRight,child:pw.Text('Total: Rs. ${total.toStringAsFixed(2)}'))]));return doc.save();});}
  @override Widget build(BuildContext context){if(loading&&error==null&&rows.isEmpty)return const Scaffold(body:Center(child:CircularProgressIndicator()));return Scaffold(appBar:AppBar(title:const Text('Reports'),actions:[IconButton(onPressed:pdf,icon:const Icon(Icons.picture_as_pdf))]),body:ListView(padding:const EdgeInsets.all(16),children:[DropdownButtonFormField<String>(initialValue:report,decoration:const InputDecoration(labelText:'Report',border:OutlineInputBorder()),items:types.map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v){if(v!=null){setState(()=>report=v);_load();}}),const SizedBox(height:10),DropdownButtonFormField<String>(initialValue:period,decoration:const InputDecoration(labelText:'Period',border:OutlineInputBorder()),items:const['Daily','Monthly','Quarterly','6 Monthly','Yearly'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v){if(v!=null)setPeriod(v);}),if(report=='Stock Management')... [const SizedBox(height:10),DropdownButtonFormField<String>(initialValue:stockScope,decoration:const InputDecoration(labelText:'Stock Location',border:OutlineInputBorder()),items:(retailUser?const['Retail Shops']:const['Production Unit','Retail Shops','All']).map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v){if(v!=null){setState(()=>stockScope=v);_load();}})],if(report=='Sales'||report=='Outstanding'||report=='Commission')... [const SizedBox(height:10),if(!retailUser)DropdownButtonFormField<String?>(initialValue:shopId,decoration:const InputDecoration(labelText:'Retail Shop',border:OutlineInputBorder()),items:[const DropdownMenuItem<String?>(value:null,child:Text('All Retail Shops')),...shops.map((x)=>DropdownMenuItem<String?>(value:x['id'].toString(),child:Text(x['name']?.toString()??'')))],onChanged:(v){setState(()=>shopId=v);_load();}),const SizedBox(height:10),DropdownButtonFormField<String?>(initialValue:productId,decoration:const InputDecoration(labelText:'Product',border:OutlineInputBorder()),items:[const DropdownMenuItem<String?>(value:null,child:Text('All Products')),...products.map((x)=>DropdownMenuItem<String?>(value:x['id'].toString(),child:Text(x['name']?.toString()??'')))],onChanged:(v){setState(()=>productId=v);_load();})],const SizedBox(height:14),if(error!=null)Text(error!,style:const TextStyle(color:Colors.red)),if(loading)const LinearProgressIndicator(),if(!loading&&rows.isEmpty)const Padding(padding:EdgeInsets.all(30),child:Text('No data found for selected period.',textAlign:TextAlign.center)),...rows.map((x)=>Card(child:ListTile(title:Text(particular(x)),subtitle:Text(x['date']==null?'${x['location']??''}':date(d(x['date']))),trailing:Text(report=='Stock Management'?'${amount(x).toStringAsFixed(2)} Box':money(amount(x)),style:const TextStyle(fontWeight:FontWeight.bold)))),if(rows.isNotEmpty)Padding(padding:const EdgeInsets.all(16),child:Text('TOTAL: ${money(total)}',textAlign:TextAlign.right,style:const TextStyle(fontSize:18,fontWeight:FontWeight.bold)))]) );}
}
